import yfinance as yf
import pandas as pd
import numpy as np
import matplotlib.pyplot as plt

# ==========================================
# 1. FULL TIME MATRIX DATA (2018 - 2026)
# ==========================================
matrices = {
    2018: "",
    2019: "",
    2020: "",
    2021: "",
    2022: "",
    2023: "",
    2024: "",
    2025: "",
    2026: ""
}

# ==========================================
# 2. DATA LOADING
# ==========================================
print("Downloading market data (2018-2026)...")
df = yf.download("BZ=F", start="2018-01-01", end="2026-12-31", progress=False, auto_adjust=True)
if isinstance(df.columns, pd.MultiIndex): df.columns = df.columns.get_level_values(0)

def get_val(row):
    yr = row.name.year
    if yr in matrices:
        day_idx = row.name.dayofyear - 1
        m_str = matrices[yr]
        if day_idx < len(m_str): return int(m_str[day_idx])
    return 0
df['matrix_val'] = df.apply(get_val, axis=1)

# ==========================================
# 3. STRATEGY LOGIC (EARLY ENTRY 8 DAYS)
# ==========================================
df['short_today'] = df['matrix_val'].apply(lambda x: 1 if x in [5, 7, 9] else 0)
df['long_today'] = df['matrix_val'].apply(lambda x: 1 if x in [1, 8] else 0)

df['short_3d'] = df['short_today'].rolling(window=3).sum()
df['long_3d'] = df['long_today'].rolling(window=3).sum()

df['future_short_wall'] = df['short_3d'].shift(-8)
df['future_long_wall'] = df['long_3d'].shift(-8)

price_falling = df['Close'] < df['Close'].shift(3)
price_rising = df['Close'] > df['Close'].shift(3)

df['position'] = 0
current_pos = 0

for i in range(len(df)):
    if df['future_long_wall'].iloc[i] >= 2 and price_rising.iloc[i]:
        current_pos = 1
    elif df['future_short_wall'].iloc[i] >= 2 and price_falling.iloc[i]:
        current_pos = -1
    elif current_pos == 1 and df['future_short_wall'].iloc[i] >= 2:
        current_pos = 0
    elif current_pos == -1 and df['future_long_wall'].iloc[i] >= 2:
        current_pos = 0
        
    df.iloc[i, df.columns.get_loc('position')] = current_pos

# ==========================================
# 4. RISK MANAGEMENT & RETURNS
# ==========================================
POSITION_SIZE = 0.20 
df['weighted_position'] = df['position'].shift(1).fillna(0) * POSITION_SIZE
df['market_return'] = df['Close'].pct_change().fillna(0)
df['strategy_return'] = df['weighted_position'] * df['market_return']
df['cum_strategy'] = (1 + df['strategy_return']).cumprod()

# ==========================================
# 5. PERFORMANCE METRICS
# ==========================================
total_return = (df['cum_strategy'].iloc[-1] - 1) * 100
market_return = (df['Close'].iloc[-1] / df['Close'].iloc[0] - 1) * 100

trades = df[df['weighted_position'] != 0].copy()
trades['is_win'] = trades['strategy_return'] > 0
win_rate = (trades['is_win'].sum() / len(trades)) * 100 if len(trades) > 0 else 0

rolling_max = df['cum_strategy'].cummax()
drawdown = (df['cum_strategy'] / rolling_max) - 1
max_drawdown = drawdown.min() * 100

trading_days = 252
mean_daily_return = df['strategy_return'].mean()
std_daily_return = df['strategy_return'].std()
annualized_return = mean_daily_return * trading_days
annualized_volatility = std_daily_return * np.sqrt(trading_days)
sharpe_ratio = annualized_return / annualized_volatility if annualized_volatility > 0 else 0
negative_returns = df[df['strategy_return'] < 0]['strategy_return']
downside_volatility = negative_returns.std() * np.sqrt(trading_days)
sortino_ratio = annualized_return / downside_volatility if downside_volatility > 0 else 0

print("\n" + "="*50)
print("STRATEGY PERFORMANCE (2018-2026)")
print("="*50)
print(f"Total Return: {total_return:.2f}%")
print(f"Market Return: {market_return:.2f}%")
print(f"Win Rate: {win_rate:.2f}%")
print(f"Max Drawdown: {max_drawdown:.2f}%")
print(f"Sharpe Ratio: {sharpe_ratio:.2f}")
print(f"Sortino Ratio: {sortino_ratio:.2f}")
print("="*50)

plt.figure(figsize=(12, 6))
plt.plot(df.index, (df['Close']/df['Close'].iloc[0])*100, label='Brent (Buy & Hold)', color='gray', alpha=0.6)
plt.plot(df.index, df['cum_strategy']*100, label='Time Matrix Strategy (8-Day Early Entry)', color='blue', linewidth=2)
plt.title('Quantitative Time-Series Discretization Strategy')
plt.legend()
plt.grid(True)
plt.show()
